  1190→            };
  1191→        }
  1192→
  1193→        let block_roots =
  1194→            self.get_block_roots_for_slot_range(req.start_slot, req.count, "DataColumnsByRange")?;
  1195→        let mut data_columns_sent = 0;
  1196→
  1197→        // Only attempt lookups for columns the node has advertised and is responsible for maintaining custody of.
