  1245→        }
  1246→
  1247→        let current_slot = self
  1248→            .chain
  1249→            .slot()
  1250→            .unwrap_or_else(|_| self.chain.slot_clock.genesis_slot());
  1251→
  1252→        debug!(
  1253→            %peer_id,
  1254→            start_slot = req.start_slot,
  1255→            %current_slot,
