  1264→    /// Helper function to ensure single item protocol always end with either a single chunk or an
  1265→    /// error
  1266→    fn terminate_response_single_item<R, F: Fn(R) -> Response<T::EthSpec>>(
  1267→        &self,
  1268→        peer_id: PeerId,
  1269→        inbound_request_id: InboundRequestId,
  1270→        result: Result<R, (RpcErrorResponse, String)>,
  1271→        into_response: F,
